type MonetaryFact = {
  partition: string; seq: string; schemaVersion: number;
  intentScope: string; intentId: string; fingerprint: string;
  result: "completed" | "rejected" | "pending";
  transferId: string; currency: string;
  entries: { accountId: string; side: "debit" | "credit"; amountMinor: string }[];
};

type RecoveryManifest = {
  partition: string; committedCut: string; ownerEpoch: string;
  schemaVersion: number; checksum: string;
  stateObject: string; // balances, holds, results, pending decisions/steps
  compatibleTail: { fromExclusive: string; generation: string };
};
